import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 예산 금액 원천 테이블이 스키마에 없어, 집행액·예산잔액은 budget_adjustment(마감·승인 상태)만으로 계산한다.
// 가정: 증액 = 추경예산·예비비, 감액(집행) = 전용·이용. 예산잔액 = 증액 합계 - 감액 합계.
const ROLE = '예산·회계 담당자';
const ADJUSTMENT_TYPES = ['추경예산', '전용', '이용', '예비비'];
const REDUCE_TYPES = ['전용', '이용'];

function isNumeric(value: unknown): boolean {
  if (typeof value === 'number') {
    return Number.isFinite(value);
  }
  if (typeof value === 'string') {
    return value.trim() !== '' && Number.isFinite(Number(value));
  }
  return false;
}

function isId(value: unknown): boolean {
  return isNumeric(value) && Number.isInteger(Number(value)) && Number(value) > 0;
}

@Controller('api/v1')
export class FnSfr00304Controller {
  @Get('/budget-items/execution-balances')
  async listBudgetItemBalances(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const page = Math.max(0, Number(query['page'] ?? 0) || 0);
    const size = Math.min(200, Math.max(1, Number(query['size'] ?? 20) || 20));
    const budgetItemId = query['budgetItemId'] === undefined || query['budgetItemId'] === '' ? null : String(query['budgetItemId']);
    const projectId = query['projectId'] === undefined || query['projectId'] === '' ? null : String(query['projectId']);
    if ((budgetItemId !== null && !isId(budgetItemId)) || (projectId !== null && !isId(projectId))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 조건 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const params = { budgetItemId, projectId, size, offset: page * size };
      const items = await db.query(
        `SELECT bi.budget_item_id AS "budgetItemId",
                bi.item_name AS "itemName",
                CAST(COALESCE(SUM(CASE WHEN ba.adjustment_type IN ('전용', '이용') THEN ba.amount ELSE 0 END), 0) AS numeric) AS "executedAmount",
                CAST(COALESCE(SUM(CASE WHEN ba.adjustment_type IN ('추경예산', '예비비') THEN ba.amount ELSE 0 END), 0)
                   - COALESCE(SUM(CASE WHEN ba.adjustment_type IN ('전용', '이용') THEN ba.amount ELSE 0 END), 0) AS numeric) AS "balanceAmount"
           FROM budget_item bi
           LEFT JOIN budget_adjustment ba
             ON ba.budget_item_id = bi.budget_item_id
            AND ba.status IN ('마감', '승인')
            AND (CAST(:projectId AS bigint) IS NULL OR ba.project_id = CAST(:projectId AS bigint))
          WHERE (CAST(:budgetItemId AS bigint) IS NULL OR bi.budget_item_id = CAST(:budgetItemId AS bigint))
          GROUP BY bi.budget_item_id, bi.item_name
          ORDER BY bi.budget_item_id
          LIMIT :size OFFSET :offset`,
        params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM budget_item bi
          WHERE (CAST(:budgetItemId AS bigint) IS NULL OR bi.budget_item_id = CAST(:budgetItemId AS bigint))`,
        { budgetItemId },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/budget-adjustments')
  @HttpCode(200)
  async createBudgetAdjustment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const adjustmentType = data['adjustmentType'];
    if (typeof adjustmentType !== 'string' || !ADJUSTMENT_TYPES.includes(adjustmentType)) {
      throw new ApiError(422, 'BUDGET_ADJUSTMENT_INVALID', '예산조정 구분을 선택해 주세요.');
    }
    if (!isId(data['budgetItemId'])) {
      throw new ApiError(422, 'BUDGET_ADJUSTMENT_INVALID', '대상 예산과목을 선택해 주세요.');
    }
    if (!isId(data['projectId'])) {
      throw new ApiError(422, 'BUDGET_ADJUSTMENT_INVALID', '프로젝트를 선택해 주세요.');
    }
    if (!isNumeric(data['amount']) || Number(data['amount']) <= 0) {
      throw new ApiError(422, 'BUDGET_ADJUSTMENT_INVALID', '조정 금액은 0보다 큰 숫자로 입력해 주세요.');
    }
    const reason = typeof data['reason'] === 'string' && data['reason'] !== '' ? data['reason'] : null;
    return transaction(async (db) => {
      const budgetItemId = String(data['budgetItemId']);
      const projectId = String(data['projectId']);
      const amount = String(data['amount']);
      const items = await db.query(
        'SELECT budget_item_id FROM budget_item WHERE budget_item_id = CAST(:budgetItemId AS bigint)',
        { budgetItemId },
      );
      if (items.length === 0) {
        throw new ApiError(422, 'BUDGET_ADJUSTMENT_INVALID', '대상 예산과목이 존재하지 않습니다.');
      }
      const projects = await db.query(
        'SELECT project_id FROM project WHERE project_id = CAST(:projectId AS bigint)',
        { projectId },
      );
      if (projects.length === 0) {
        throw new ApiError(422, 'BUDGET_ADJUSTMENT_INVALID', '프로젝트가 존재하지 않습니다.');
      }
      if (REDUCE_TYPES.includes(adjustmentType)) {
        const balances = await db.query(
          `SELECT CAST(COALESCE(SUM(CASE WHEN adjustment_type IN ('추경예산', '예비비') THEN amount ELSE 0 END), 0)
                    - COALESCE(SUM(CASE WHEN adjustment_type IN ('전용', '이용') THEN amount ELSE 0 END), 0) AS numeric) AS "balance"
             FROM budget_adjustment
            WHERE budget_item_id = CAST(:budgetItemId AS bigint)
              AND status IN ('마감', '승인')`,
          { budgetItemId },
        );
        const balance = Number(balances[0]['balance']);
        if (Number(amount) > balance) {
          throw new ApiError(422, 'BUDGET_BALANCE_INSUFFICIENT', '조정 감액 금액이 예산잔액을 초과합니다.');
        }
      }
      const rows = await db.query(
        `INSERT INTO budget_adjustment
           (budget_item_id, project_id, requester_id, adjustment_type, amount, reason, status, created_at, updated_at)
         VALUES
           (CAST(:budgetItemId AS bigint), CAST(:projectId AS bigint), CAST(:userId AS bigint), :adjustmentType, CAST(:amount AS numeric), :reason, '신청', now(), now())
         RETURNING budget_adjustment_id AS "budgetAdjustmentId", status`,
        { budgetItemId, projectId, userId: user.id, adjustmentType, amount, reason },
      );
      return rows[0];
    });
  }

  @Post('/budget-adjustments/:budgetAdjustmentId/close')
  @HttpCode(200)
  async closeBudgetAdjustment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['budgetAdjustmentId'];
    if (!isId(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '예산조정 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status FROM budget_adjustment WHERE budget_adjustment_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'BUDGET_ADJUSTMENT_NOT_FOUND', '대상 예산조정이 없습니다.');
      }
      if (rows[0]['status'] !== '신청') {
        throw new ApiError(409, 'BUDGET_ADJUSTMENT_STATUS_CONFLICT', '신청 상태의 예산조정만 마감할 수 있습니다.');
      }
      await db.execute(
        "UPDATE budget_adjustment SET status = '마감', updated_at = now() WHERE budget_adjustment_id = CAST(:id AS bigint)",
        { id },
      );
      return { status: '마감' };
    });
  }

  @Post('/budget-adjustments/:budgetAdjustmentId/cancel-close')
  @HttpCode(200)
  async cancelCloseBudgetAdjustment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['budgetAdjustmentId'];
    if (!isId(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '예산조정 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status FROM budget_adjustment WHERE budget_adjustment_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'BUDGET_ADJUSTMENT_NOT_FOUND', '대상 예산조정이 없습니다.');
      }
      if (rows[0]['status'] !== '마감') {
        throw new ApiError(409, 'BUDGET_ADJUSTMENT_STATUS_CONFLICT', '마감 상태의 예산조정만 마감취소할 수 있습니다.');
      }
      await db.execute(
        "UPDATE budget_adjustment SET status = '마감취소', updated_at = now() WHERE budget_adjustment_id = CAST(:id AS bigint)",
        { id },
      );
      return { status: '마감취소' };
    });
  }

  @Post('/budget-adjustments/:budgetAdjustmentId/submit-approval')
  @HttpCode(200)
  async submitBudgetAdjustmentApproval(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['budgetAdjustmentId'];
    if (!isId(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '예산조정 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT ba.status AS "status",
                ba.approval_document_id AS "approvalDocumentId",
                ad.approval_status AS "approvalStatus"
           FROM budget_adjustment ba
           LEFT JOIN approval_document ad ON ad.approval_document_id = ba.approval_document_id
          WHERE ba.budget_adjustment_id = CAST(:id AS bigint)`,
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'BUDGET_ADJUSTMENT_NOT_FOUND', '대상 예산조정이 없습니다.');
      }
      if (rows[0]['status'] !== '마감') {
        throw new ApiError(409, 'BUDGET_ADJUSTMENT_NOT_CLOSED', '마감된 예산조정만 상신할 수 있습니다.');
      }
      // 가정: 이미 결재문서가 연결되어 있으면 그 문서의 결재 상태를 상신 결과로 돌려준다.
      if (rows[0]['approvalDocumentId'] !== null && rows[0]['approvalDocumentId'] !== undefined) {
        return {
          approvalDocumentId: Number(rows[0]['approvalDocumentId']),
          submitResult: String(rows[0]['approvalStatus'] ?? ''),
        };
      }
      // 가정: 전자결재 모듈(S2) 호출 수단과 결재양식 ID 출처가 입력에 없어 상신하지 못하면 연계 실패로 처리한다. 상태는 유지된다.
      throw new ApiError(502, 'APPROVAL_SUBMIT_FAILED', '전자결재 연계에 실패했습니다. 잠시 후 다시 시도해 주세요.');
    });
  }
}

