import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  TextInput,
  NumberInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const TYPES: [string, string][] = [
  ['추경예산', '추경예산'],
  ['전용', '전용'],
  ['이용', '이용'],
  ['예비비', '예비비'],
];

export default function FnSfr00304Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [filterItem, setFilterItem] = useState<number | string>('');
  const [filterProject, setFilterProject] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [open, setOpen] = useState(false);
  const [handled, setHandled] = useState<Row[]>([]);
  const [actionError, setActionError] = useState('');

  const [adjustmentType, setAdjustmentType] = useState('');
  const [budgetItemId, setBudgetItemId] = useState<number | string>('');
  const [projectId, setProjectId] = useState<number | string>('');
  const [amount, setAmount] = useState<number | string>('');
  const [reason, setReason] = useState('');

  const balances = useData<Page>(
    () =>
      call<Page>('GET', '/budget-items/execution-balances', role, undefined, {
        budgetItemId: applied['budgetItemId'],
        projectId: applied['projectId'],
        page,
        size: 10,
      }),
    [role, page, applied],
  );

  const search = () => {
    setPage(0);
    setApplied({ budgetItemId: filterItem, projectId: filterProject });
  };

  const reset = () => {
    setFilterItem('');
    setFilterProject('');
    setPage(0);
    setApplied({});
  };

  const openForm = () => {
    setAdjustmentType('');
    setBudgetItemId('');
    setProjectId('');
    setAmount('');
    setReason('');
    setOpen(true);
  };

  const submitForm = async () => {
    if (adjustmentType === '') {
      throw new Error('예산조정 구분을 선택해 주세요.');
    }
    if (budgetItemId === '') {
      throw new Error('대상 예산과목을 선택해 주세요.');
    }
    if (projectId === '') {
      throw new Error('프로젝트를 선택해 주세요.');
    }
    if (amount === '' || Number(amount) <= 0 || Number.isNaN(Number(amount))) {
      throw new Error('조정 금액은 0보다 큰 숫자로 입력해 주세요.');
    }
    const result = await call('POST', '/budget-adjustments', role, {
      adjustmentType,
      budgetItemId,
      projectId,
      amount,
      reason,
    });
    setHandled([
      {
        budgetAdjustmentId: result['budgetAdjustmentId'],
        adjustmentType,
        budgetItemId,
        amount,
        status: result['status'],
      },
      ...handled,
    ]);
    setOpen(false);
    notify('예산조정을 신청했습니다.');
    balances.reload();
  };

  const changeStatus = (id: unknown, status: unknown) => {
    setHandled(
      handled.map((row) =>
        row['budgetAdjustmentId'] === id ? { ...row, status } : row,
      ),
    );
  };

  const act = async (row: Row, action: 'close' | 'cancel-close' | 'submit-approval') => {
    setActionError('');
    try {
      const id = row['budgetAdjustmentId'];
      const result = await call('POST', `/budget-adjustments/${id}/${action}`, role, {});
      if (action === 'submit-approval') {
        notify('전자결재로 상신했습니다. 결과: ' + String(result['submitResult'] ?? ''));
      } else {
        changeStatus(id, result['status']);
        notify(action === 'close' ? '마감했습니다.' : '마감을 취소했습니다.');
      }
      balances.reload();
    } catch (e) {
      setActionError(e instanceof Error ? e.message : '처리하지 못했습니다.');
    }
  };

  const data = balances.data;
  const items = data ? data.items : [];
  const balanceSum = items.reduce((sum, row) => sum + Number(row['balanceAmount'] ?? 0), 0);
  const executedSum = items.reduce((sum, row) => sum + Number(row['executedAmount'] ?? 0), 0);

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>예산 현황</h2>
        <Tiles
          items={[
            ['조회 과목', <Num value={data ? data.total : 0} />],
            ['집행액 (현재 쪽)', <Num value={executedSum} />],
            ['예산잔액 (현재 쪽)', <Num value={balanceSum} />],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>예산과목별 잔액</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="예산과목 ID">
            <LookupSelect table="budget_item" role={role} value={filterItem} onChange={setFilterItem} />
          </Field>
          <Field label="프로젝트 ID">
            <LookupSelect table="project" role={role} value={filterProject} onChange={setFilterProject} />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={openForm}>예산조정 신청</button>
        </Band>
        {balances.error !== '' && <ErrorText text={balances.error} />}
        <DataTable
          columns={[
            { key: 'itemName', label: '예산과목 명칭' },
            { key: 'executedAmount', label: '집행액', render: (row) => <Num value={row['executedAmount']} /> },
            { key: 'balanceAmount', label: '예산잔액', render: (row) => <Num value={row['balanceAmount']} /> },
          ]}
          rows={items}
          empty="조회된 예산과목이 없습니다."
        />
        <Pager page={data ? data.page : 0} size={data ? data.size : 10} total={data ? data.total : 0} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>처리한 예산조정</h2>
        {actionError !== '' && <ErrorText text={actionError} />}
        <DataTable
          columns={[
            { key: 'adjustmentType', label: '예산조정 구분' },
            { key: 'budgetItemId', label: '예산과목', render: (row) => <RefName table="budget_item" role={role} value={row['budgetItemId']} /> },
            { key: 'amount', label: '조정 금액', render: (row) => <Num value={row['amount']} /> },
            { key: 'status', label: '상태', render: (row) => <Badge value={row['status']} /> },
            {
              key: 'actions',
              label: '처리',
              render: (row) => (
                <span>
                  {row['status'] === '신청' && (
                    <button type="button" onClick={() => act(row, 'close')}>마감</button>
                  )}
                  {row['status'] === '마감' && (
                    <button type="button" onClick={() => act(row, 'cancel-close')}>마감취소</button>
                  )}
                  {row['status'] === '마감' && (
                    <button type="button" onClick={() => act(row, 'submit-approval')}>전자결재 상신</button>
                  )}
                </span>
              ),
            },
          ]}
          rows={handled}
          empty="이 화면에서 처리한 예산조정이 없습니다."
        />
      </section>
      {open && (
        <Drawer title="예산조정 신청" onClose={() => setOpen(false)}>
          <Form onSubmit={submitForm} submit="신청">
            <Field label="예산조정 구분" required>
              <Select value={adjustmentType} onChange={setAdjustmentType} options={TYPES} />
            </Field>
            <Field label="대상 예산과목 ID" required hint="위 표에서 집행액과 예산잔액을 확인한 뒤 선택하세요.">
              <LookupSelect table="budget_item" role={role} value={budgetItemId} onChange={setBudgetItemId} />
            </Field>
            <Field label="프로젝트 ID" required>
              <LookupSelect table="project" role={role} value={projectId} onChange={setProjectId} />
            </Field>
            <Field label="조정 금액" required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
            <Field label="조정 사유" wide>
              <TextInput value={reason} onChange={setReason} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
